// Create a text index on one field
await articles.createIndex({ title: 'text' });

// Create a text index on multiple fields
await articles.createIndex({
  title: 'text',
  body: 'text',
  tags: 'text'
});
// Now $text searches across all three fields simultaneously

// Weighted text index — title matches count more than body
await articles.createIndex(
  { title: 'text', body: 'text' },
  { weights: { title: 10, body: 1 }, name: 'article_text_index' }
);
// A word match in title scores 10x higher than in body

// Language-specific index (uses correct stemming and stop words)
await articles.createIndex(
  { title: 'text', body: 'text' },
  { default_language: 'english' }  // default is English
);

// Note: a collection can have ONLY ONE text index

// Basic search — finds documents containing 'mongodb' OR 'database'
const results = await articles.find(
  { $text: { $search: 'mongodb database' } }
).toArray();

// Phrase search — exact phrase in double quotes
const phraseResults = await articles.find(
  { $text: { $search: '"aggregation pipeline"' } }  // exact phrase
).toArray();

// Negation — find documents with 'mongodb' but NOT 'sql'
const noSQL = await articles.find(
  { $text: { $search: 'mongodb -sql' } }  // minus prefix excludes a term
).toArray();

// Get relevance score and sort by it
const ranked = await articles.find(
  { $text: { $search: 'mongodb aggregation pipeline' } },
  { projection: { score: { $meta: 'textScore' }, title: 1, _id: 0 } }
).sort({ score: { $meta: 'textScore' } })  // sort by relevance
  .toArray();

console.log('Top results:');
ranked.forEach(r => console.log(r.title, '— score:', r.score.toFixed(2)));

// Combine $text with other filters
const recentResults = await articles.find({
  $text: { $search: 'nodejs express' },   // text search
  status: 'published',                     // regular filter
  publishedAt: { $gte: new Date('2025-01-01') }  // date filter
}, {
  projection: { title: 1, score: { $meta: 'textScore' }, publishedAt: 1 }
}).sort({ score: { $meta: 'textScore' } })
  .limit(10)
  .toArray();

// Atlas Search — uses $search aggregation stage (not $text)
// Requires: MongoDB Atlas cluster with an Atlas Search index defined

// Basic Atlas Search
const results = await articles.aggregate([
  {
    $search: {
      index: 'default',  // name of your Atlas Search index
      text: {
        query: 'mongodb aggregation',
        path: ['title', 'body'],  // fields to search
        fuzzy: { maxEdits: 1 }   // tolerate 1 typo!
      }
    }
  },
  {
    $project: {
      title: 1,
      score: { $meta: 'searchScore' }
    }
  },
  { $sort: { score: -1 } },
  { $limit: 10 }
]).toArray();

// Autocomplete (as you type) — requires autocomplete field mapping in Atlas Search index
const suggestions = await articles.aggregate([
  {
    $search: {
      autocomplete: {
        query: 'mong',           // partial input
        path: 'title',
        fuzzy: { maxEdits: 1 }  // tolerate typos in autocomplete too
      }
    }
  },
  { $limit: 5 },
  { $project: { title: 1, _id: 0 } }
]).toArray();

console.log('Suggestions:', suggestions.map(s => s.title));
